import re, subprocess, json
import pandas as pd
from pathlib import Path

pdf_path=Path('/root/employees_backup.pdf')
excel_path=Path('/root/employees_current.xlsx')

# Extract PDF table via pdftotext -layout
text=subprocess.check_output(['pdftotext','-layout',str(pdf_path),'-'], text=True)
rows=[]
for line in text.splitlines():
    line=line.strip()
    if not line.startswith('EMP'):
        continue
    parts=re.split(r'\s{2,}', line)
    if len(parts)!=8:
        # unexpected; skip
        continue
    emp_id, first, last, dept, position, salary, years_loc, score = parts
    m=re.match(r'^(\d+)\s+(.*)$', years_loc)
    if not m:
        # if no match, maybe missing location
        years=years_loc
        location=''
    else:
        years, location = m.group(1), m.group(2)
    rows.append({
        'ID': emp_id,
        'First': first,
        'Last': last,
        'Dept': dept,
        'Position': position,
        'Salary': int(salary.replace(',','')) if salary else None,
        'Years': int(years) if years!='' else None,
        'Location': location,
        'Score': float(score) if '.' in score else int(score) if score else None,
    })

old_df=pd.DataFrame(rows)
# read excel
new_df=pd.read_excel(excel_path)
print('excel columns', list(new_df.columns))
print('old rows', len(old_df), 'new rows', len(new_df))

# Normalize column names maybe
# Ensure columns names match expected
expected=['ID','First','Last','Dept','Position','Salary','Years','Location','Score']
# if excel has different case/spaces
col_map={c: c.strip().title() for c in new_df.columns}
# But we need exact names; let's build mapping by lower
lower_map={c.lower(): c for c in new_df.columns}

# Reindex to expected using lower-case matching
new_df_norm=pd.DataFrame()
for col in expected:
    key=col.lower()
    if key in lower_map:
        new_df_norm[col]=new_df[lower_map[key]]
    else:
        raise SystemExit(f'Missing column {col} in excel')

# convert types
new_df_norm['Salary']=new_df_norm['Salary'].apply(lambda x: int(x) if pd.notna(x) else None)
new_df_norm['Years']=new_df_norm['Years'].apply(lambda x: int(x) if pd.notna(x) else None)

# Score: keep int if no decimal

def parse_score(x):
    if pd.isna(x):
        return None
    # if x already int/float
    if isinstance(x, float):
        if x.is_integer():
            return int(x)
        return float(x)
    if isinstance(x, int):
        return x
    # string
    s=str(x)
    if '.' in s:
        try:
            f=float(s)
            return int(f) if f.is_integer() else f
        except:
            return s
    else:
        try:
            return int(s)
        except:
            return s

new_df_norm['Score']=new_df_norm['Score'].apply(parse_score)

# strings for text fields
for col in ['ID','First','Last','Dept','Position','Location']:
    new_df_norm[col]=new_df_norm[col].apply(lambda x: '' if pd.isna(x) else str(x))

# old_df ensure types
old_df['Salary']=old_df['Salary'].apply(lambda x: int(x) if x is not None else None)
old_df['Years']=old_df['Years'].apply(lambda x: int(x) if x is not None else None)

# Score already parsed in old_df

# convert text fields to string
for col in ['ID','First','Last','Dept','Position','Location']:
    old_df[col]=old_df[col].apply(lambda x: '' if x is None else str(x))

# Build dicts
old_map={row['ID']: row for row in old_df.to_dict(orient='records')}
new_map={row['ID']: row for row in new_df_norm.to_dict(orient='records')}

# deleted employees
deleted=sorted([emp_id for emp_id in old_map.keys() if emp_id not in new_map])

# modified employees
modified=[]
fields=expected[1:]  # all fields except ID? But compare all except ID
for emp_id in sorted(old_map.keys() & new_map.keys()):
    old=old_map[emp_id]
    new=new_map[emp_id]
    for field in fields:
        if old.get(field)!=new.get(field):
            modified.append({
                'id': emp_id,
                'field': field,
                'old_value': old.get(field),
                'new_value': new.get(field)
            })

# sort modified by id then field
modified.sort(key=lambda x: (x['id'], x['field']))

result={'deleted_employees': deleted, 'modified_employees': modified}

print('deleted', len(deleted), 'modified entries', len(modified))

out_path=Path('/root/diff_report.json')
with out_path.open('w') as f:
    json.dump(result, f, indent=2)

print('written', out_path)
